                children: `
                .pos-held-orders-container {
                    height: 100vh;
                    display: flex;
                    flex-direction: column;
                    background: var(--pos-bg-main);
                    color: var(--pos-text-primary);
                    font-family: var(--pos-font-family);
                }

                .held-header {
                    height: 80px;
                    display: flex;
                    align-items: center;
                    justify-content: space-between;
                    padding: 0 32px;
                    background: var(--pos-bg-surface);
                    border-bottom: 1px solid var(--pos-border-subtle);
                    z-index: 10;
                }

                .header-left {
                    display: flex;
                    align-items: center;
                    gap: 24px;
                }

                .main-layout {
                    flex: 1;
                    display: flex;
                    overflow: hidden;
                    padding: 24px;
                    gap: 24px;
                }

                .left-column {
                    width: 420px;
                    display: flex;
                    flex-direction: column;
                    gap: 16px;
                }

                .search-container {
                    position: relative;
                }

                .search-icon {
                    position: absolute;
                    left: 18px;
                    top: 50%;
                    transform: translateY(-50%);
                    color: var(--pos-text-muted);
                }

                .search-input {
                    width: 100%;
                    height: 60px;
                    background: var(--pos-bg-surface);
                    border: 1px solid var(--pos-border-subtle);
                    border-radius: 16px;
                    padding-left: 52px;
                    font-size: 16px;
                    font-weight: 600;
                    color: var(--pos-text-primary);
                    outline: none;
                    transition: all 0.2s;
                }

                .search-input:focus {
                    border-color: var(--pos-action-primary);
                    box-shadow: 0 4px 12px rgba(31, 164, 169, 0.08);
                }

                .orders-list {
                    flex: 1;
                    overflow-y: auto;
                    display: flex;
                    flex-direction: column;
                    gap: 12px;
                    padding-right: 4px;
                }

                .order-card {
                    background: var(--pos-bg-surface);
                    border: 1px solid var(--pos-border-subtle);
                    border-radius: 20px;
                    padding: 20px;
                    cursor: pointer;
                    transition: all 0.2s;
                    text-align: left;
                    width: 100%;
                }

                .order-card:hover {
                    border-color: var(--pos-text-muted);
                    transform: translateY(-2px);
                }

                .order-card.selected {
                    background: var(--pos-action-secondary);
                    border-color: var(--pos-action-primary);
                }

                .avatar {
                    width: 52px;
                    height: 52px;
                    border-radius: 14px;
                    background: rgba(31, 164, 169, 0.1);
                    color: var(--pos-action-primary);
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    font-weight: 800;
                    font-size: 18px;
                }

                .details-panel {
                    flex: 1;
                    background: var(--pos-bg-surface);
                    border: 1px solid var(--pos-border-subtle);
                    border-radius: 24px;
                    display: flex;
                    flex-direction: column;
                    overflow: hidden;
                }

                .details-header {
                    padding: 40px;
                    border-bottom: 1px solid var(--pos-border-subtle);
                    background: #FAFBFC;
                }

                .reason-box {
                    background: #FFFBEB;
                    border: 1px solid #FEF3C7;
                    border-radius: 16px;
                    padding: 20px;
                    margin-top: 24px;
                    display: flex;
                    gap: 16px;
                }

                .items-content {
                    padding: 40px;
                    flex: 1;
                    overflow-y: auto;
                }

                .items-list {
                    display: grid;
                    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
                    gap: 16px;
                }

                .item-card {
                    padding: 16px 20px;
                    background: var(--pos-bg-main);
                    border: 1px solid var(--pos-border-subtle);
                    border-radius: 12px;
                    display: flex;
                    align-items: center;
                    gap: 12px;
                    font-weight: 600;
                }

                .details-footer {
                    padding: 32px 40px;
                    background: #FAFBFC;
                    border-top: 1px solid var(--pos-border-subtle);
                    display: flex;
                    gap: 20px;
                    align-items: center;
                }

                .resume-button {
                    flex: 2;
                    height: 64px;
                    background: var(--pos-action-primary);
                    color: white;
                    border: none;
                    border-radius: 16px;
                    font-size: 18px;
                    font-weight: 800;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    gap: 12px;
                    cursor: pointer;
                    transition: all 0.2s;
                    text-transform: uppercase;
                    letter-spacing: 0.1em;
                }

                .resume-button:hover {
                    filter: brightness(1.1);
                    transform: translateY(-2px);
                    box-shadow: 0 4px 12px rgba(31, 164, 169, 0.2);
                }

                .void-button {
                    flex: 1;
                    height: 64px;
                    background: #FEE2E2;
                    color: #EF4444;
                    border: 2px solid #FEE2E2;
                    border-radius: 16px;
                    font-size: 16px;
                    font-weight: 700;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    gap: 12px;
                    cursor: pointer;
                    transition: all 0.2s;
                }

                .void-button:hover {
                    background: #FECACA;
                    border-color: #F87171;
                }

                .empty-state {
                    flex: 1;
                    display: flex;
                    flex-direction: column;
                    align-items: center;
                    justify-content: center;
                    color: var(--pos-text-muted);
                }

                .orders-list::-webkit-scrollbar { width: 4px; }
                .orders-list::-webkit-scrollbar-thumb { background: var(--pos-border-subtle); border-radius: 10px; }
            `
